import type { Metadata } from "next";
import { GoogleAnalytics } from '@next/third-parties/google'
import { getMessages, getLocale } from "next-intl/server";
import type { Locale } from "@ziziyi/utils";
import { I18nProvider } from "@/components/i18n-provider";
import { ProgressProvider } from "@/components/progress-provider";
import { AppToaster } from "@/components/app-toaster";
import "./globals.css";
import { sitePath } from "@/utils/site-path";

const publicSiteUrl = process.env.NEXT_PUBLIC_SITE_URL?.replace(/\/$/, "");

export const metadata: Metadata = {
  ...(publicSiteUrl ? { metadataBase: new URL(publicSiteUrl) } : {}),
  title: {
    default: "V-Office — Free Online Word, Excel & PowerPoint Editor",
    template: "%s",
  },
  description:
    "Free online office suite. Open, view, and edit Word, Excel, and PowerPoint documents directly in your browser. No upload, no login — your files stay private.",
  keywords: [
    "web office",
    "online office suite",
    "Word online",
    "Excel online",
    "PowerPoint online",
    "DOCX viewer",
    "DOCX editor",
    "XLSX editor",
    "PPTX editor",
    "open docx online",
    "edit excel online",
    "serverless office",
    "privacy first",
    "V-Office",
  ],
  icons: {
    icon: [
      { url: sitePath("/favicon.ico"), sizes: "any" },
      { url: sitePath("/logo.svg"), type: "image/svg+xml" },
    ],
    apple: sitePath("/logo.png"),
  },
  openGraph: {
    siteName: "V-Office",
    type: "website",
    locale: "en_US",
  },
  twitter: {
    card: "summary_large_image",
    creator: "@nicezizi",
  },
  robots: {
    index: true,
    follow: true,
  },
  other: {
    "mobile-web-app-capable": "yes",
    "apple-mobile-web-app-capable": "yes",
    "apple-mobile-web-app-title": "V-Office",
  },
};

export default async function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  const messages = await getMessages();
  const locale = await getLocale();

  const preload = () => {
    const theme = document.cookie.match(/theme=([^;]+)/)?.[1] || "";
    const dark = window.matchMedia("(prefers-color-scheme: dark)").matches;
    const isDark = theme == "dark" || (dark && theme != "light");
    document.documentElement.classList.toggle("dark", isDark);
  };

  const jsonLd = {
    "@context": "https://schema.org",
    "@type": "WebApplication",
    name: "V-Office",
    ...(publicSiteUrl ? { url: publicSiteUrl } : {}),
    description:
      "Open, view, and edit Word, Excel, and PowerPoint documents directly in your browser. No upload, no server — your files stay private.",
    applicationCategory: "BusinessApplication",
    operatingSystem: "Any",
    offers: {
      "@type": "Offer",
      price: "0",
      priceCurrency: "USD",
    },
    featureList: [
      "Edit DOCX, XLSX, PPTX files",
      "No file upload required",
      "Privacy-first — files stay local",
      "Free templates",
      "Browser extension for drag & drop",
    ],
  };

  return (
    <html suppressHydrationWarning>
      <head>
        <script>{`(${preload.toString()})()`}</script>
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
        />
        {/* VOS deployments write this file from the container entrypoint
            (VOS_APP_VERSION); it does not exist on standalone deployments. */}
        <script
          src={`${process.env.NEXT_PUBLIC_BASE_PATH ?? ""}/runtime-config.js`}
        />
      </head>
      <body>
        <ProgressProvider>
          <I18nProvider initialMessages={messages} initialLocale={locale as Locale}>
            {children}
          </I18nProvider>
          <AppToaster />
        </ProgressProvider>
      </body>
      <GoogleAnalytics gaId="G-EFLBPT6TS8" />
    </html>
  );
}
